function fewestSprinklers(n: number, ranges: number[]): number {
  const INF = Number.MAX_SAFE_INTEGER;
  const best = new Array(n + 1).fill(INF);
  best[0] = 0;
  // group intervals by left end so best[l] is final before it is used
  const byLeft: number[][] = Array.from({ length: n + 1 }, () => []);
  ranges.forEach((r, i) => { if (r > 0) byLeft[Math.max(0, i - r)].push(Math.min(n, i + r)); });
  for (let l = 0; l <= n; l++) {
    if (best[l] === INF) continue;
    for (const right of byLeft[l]) {
      for (let x = l + 1; x <= right; x++) best[x] = Math.min(best[x], best[l] + 1);
    }
  }
  return best[n] === INF ? -1 : best[n];
}

