class Solution:
    def fewestSprinklers(self, n: int, ranges: List[int]) -> int:
        INF = float("inf")
        best = [INF] * (n + 1)
        best[0] = 0
        # group intervals by left end so best[l] is final before it is used
        by_left = [[] for _ in range(n + 1)]
        for i, r in enumerate(ranges):
            if r > 0:
                by_left[max(0, i - r)].append(min(n, i + r))
        for l in range(n + 1):
            if best[l] == INF:
                continue
            for right in by_left[l]:
                for x in range(l + 1, right + 1):
                    best[x] = min(best[x], best[l] + 1)
        return -1 if best[n] == INF else best[n]

