function fewestSprinklers(n: number, ranges: number[]): number {
  const reach = new Array(n + 1).fill(0);
  ranges.forEach((r, i) => {
    const l = Math.max(0, i - r);
    reach[l] = Math.max(reach[l], Math.min(n, i + r));
  });
  let count = 0, end = 0, far = 0;
  for (let p = 0; p < n; p++) {
    far = Math.max(far, reach[p]);
    if (p === end) {
      if (far <= p) return -1; // a dry gap right after p
      count++;
      end = far;
    }
  }
  return count;
}

